        ts = np.asarray(ts, float)
        def rhs(t, y):
            C = pk_conc(dose, t)
            inh = p['Imax']*C**p['gam']/(p['IC50']**p['gam']+C**p['gam'])
            return [p['kout']*p['R0']*(1-inh) - p['kout']*y[0]]
        sol = solve_ivp(rhs, [0, ts.max()], [p['R0']], t_eval=ts, rtol=1e-8, atol=1e-8)
        return sol.y[0]
    return per_dose(df, solve_one)

